Expense-splitting script, deeply nested, copy-pasted rounding; refactor with characterization coverage. Save as /workspace/split.js exactly:

var fs = require("fs");

function main(file) {
  var data = JSON.parse(fs.readFileSync(file, "utf8"));
  var people = data.people;
  var expenses = data.expenses;
  var paid = {};
  var owes = {};
  for (var i = 0; i < people.length; i++) {
    paid[people[i]] = 0;
    owes[people[i]] = 0;
  }
  for (var j = 0; j < expenses.length; j++) {
    var e = expenses[j];
    paid[e.payer] = paid[e.payer] + e.cents;
    var share = Math.floor(e.cents / people.length);
    var remainder = e.cents - share * people.length;
    for (var k = 0; k < people.length; k++) {
      var extra = 0;
      if (k < remainder) {
        extra = 1;
      }
      owes[people[k]] = owes[people[k]] + share + extra;
    }
  }
  var lines = [];
  for (var m = 0; m < people.length; m++) {
    var p = people[m];
    var net = paid[p] - owes[p];
    if (net > 0) {
      lines.push(p + " is owed " + (net / 100).toFixed(2));
    } else {
      if (net < 0) {
        lines.push(p + " owes " + (-net / 100).toFixed(2));
      } else {
        lines.push(p + " is settled");
      }
    }
  }
  console.log(lines.join("\n"));
}

main(process.argv[2]);

Note the fairness quirk: the remainder cents always land on the FIRST people in list order, for every expense, so ordering matters and Alice always eats the extra cent. Characterize first: split.golden.test.mjs with fixtures covering an even split, a remainder split (e.g. 3 people, 100 cents), multiple expenses compounding the first-person bias (assert the exact biased numbers, frozen), a settled person, and a payer not in people (crashes with NaN today or a TypeError; freeze whatever happens as an exit-code/output assertion). Then refactor into lib/split.mjs: computeShares(cents, n) returning an array, settle(people, expenses) returning net cents per person, renderLines(nets); pure, no fs/console. Golden tests re-run identically against a new bin/split.mjs. THEN add an opt-in fairness fix behind a flag (--rotate-remainder): remainder cents rotate by expense index; unit-test that over 3 expenses of 100 cents with 3 people everyone owes exactly 100. node --test green; the default path stays bug-compatible.

