// Characterization (golden) tests for the expense splitter.
//
// These tests freeze the CURRENT behavior of the legacy script split.js,
// including its fairness quirk: remainder cents always land on the FIRST
// people in list order for every expense (Alice always eats the extra cent).
//
// Each fixture is run through BOTH the legacy entrypoint (split.js) and the
// refactored entrypoint (bin/split.mjs) with identical expectations, so any
// behavior change in the refactor fails here.
import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.dirname(fileURLToPath(import.meta.url));
const LEGACY = path.join(root, "split.js");
const REFACTORED = path.join(root, "bin", "split.mjs");
const fixture = (name) => path.join(root, "fixtures", name);

function run(script, fixturePath) {
  const stdout = execFileSync(process.execPath, [script, fixturePath], {
    encoding: "utf8",
  });
  return stdout;
}

// Frozen golden outputs (bug-compatible, incl. trailing newline from console.log).
const GOLDEN = {
  // 200 cents / 2 people: even, no remainder.
  "even.json": ["Alice is owed 1.00", "Bob owes 1.00"].join("\n") + "\n",

  // 100 cents / 3 people: share=33, remainder=1 -> Alice gets the extra cent.
  "remainder.json":
    ["Alice is owed 0.66", "Bob owes 0.33", "Carol owes 0.33"].join("\n") +
    "\n",

  // Three expenses compound the bias: Alice over-pays by 1 cent PER EXPENSE.
  "compound-bias.json":
    ["Alice is owed 1.98", "Bob owes 0.99", "Carol owes 0.99"].join("\n") +
    "\n",

  // Both nets are exactly zero -> "is settled".
  "settled.json": ["Alice is settled", "Bob is settled"].join("\n") + "\n",

  // CHARACTERIZED QUIRK (not a crash): payer "Zed" is absent from people[],
  // so paid["Zed"] becomes NaN silently; Zed never appears in the output
  // because rendering iterates people[]. Exit code stays 0. Freeze as-is.
  "payer-not-in-people.json":
    ["Alice owes 0.34", "Bob owes 0.33", "Carol owes 0.33"].join("\n") + "\n",
};

for (const [name, expected] of Object.entries(GOLDEN)) {
  test(`golden: ${name} (legacy split.js)`, () => {
    const out = run(LEGACY, fixture(name));
    assert.equal(out, expected);
  });

  test(`golden: ${name} (refactored bin/split.mjs)`, () => {
    const out = run(REFACTORED, fixture(name));
    assert.equal(out, expected);
  });
}

