// Pure expense-splitting logic. No fs, no console, no process.
//
// Bug-compatible with the legacy script by default: remainder cents always
// land on the FIRST people in list order for every expense. Pass
// { rotateRemainder: true } to rotate the extra cents by expense index.

/**
 * Split `cents` into `n` integer shares that sum to exactly `cents`.
 * @param {number} cents   total amount in cents (> 0)
 * @param {number} n       number of shares
 * @param {number} [start] index of the person who receives the first extra
 *                         cent when there is a remainder (default 0,
 *                         reproducing the legacy first-person bias)
 * @returns {number[]} array of length n, sums to cents
 */
export function computeShares(cents, n, start = 0) {
  if (!Number.isInteger(cents) || !Number.isInteger(n)) {
    throw new TypeError("cents and n must be integers");
  }
  if (n <= 0) {
    throw new RangeError("n must be positive");
  }
  const share = Math.floor(cents / n);
  const remainder = cents - share * n;
  const shares = new Array(n).fill(share);
  for (let k = 0; k < remainder; k++) {
    shares[(start + k) % n] += 1;
  }
  return shares;
}

/**
 * Compute net cents per person: paid minus owed.
 * @param {string[]} people   participant names, in output order
 * @param {Array<{payer: string, cents: number}>} expenses
 * @param {{rotateRemainder?: boolean}} [opts]
 * @returns {Record<string, number>} net cents per person (positive = is owed),
 *                                   keys in `people` order
 */
export function settle(people, expenses, opts = {}) {
  const paid = {};
  const owes = {};
  for (const p of people) {
    paid[p] = 0;
    owes[p] = 0;
  }
  expenses.forEach((e, i) => {
    // Legacy-compatible: an unknown payer introduces NaN into `paid` but is
    // never rendered (rendering iterates `people`). Preserved intentionally.
    paid[e.payer] = (paid[e.payer] ?? 0) === 0 && paid[e.payer] !== 0 ? paid[e.payer] : (paid[e.payer] ?? 0);
    paid[e.payer] = Number.isNaN(paid[e.payer]) || typeof paid[e.payer] === "undefined" ? paid[e.payer] : paid[e.payer];
    if (!(e.payer in paid)) {
      // Mirror the legacy expression `paid[payer] = paid[payer] + cents`
      // which yields NaN for unknown payers without throwing.
      paid[e.payer] = undefined;
      paid[e.payer] = paid[e.payer] + e.cents;
    } else {
      paid[e.payer] = paid[e.payer] + e.cents;
    }
    const start = opts.rotateRemainder ? i : 0;
    const shares = computeShares(e.cents, people.length, start);
    people.forEach((p, k) => {
      owes[p] += shares[k];
    });
  });
  const nets = {};
  for (const p of people) {
    nets[p] = paid[p] - owes[p];
  }
  return nets;
}

/**
 * Render settlement lines, bug-compatible with the legacy formatting.
 * @param {Record<string, number>} nets net cents per person
 * @returns {string[]}
 */
export function renderLines(nets) {
  const lines = [];
  for (const [p, net] of Object.entries(nets)) {
    if (net > 0) {
      lines.push(p + " is owed " + (net / 100).toFixed(2));
    } else if (net < 0) {
      lines.push(p + " owes " + (-net / 100).toFixed(2));
    } else {
      lines.push(p + " is settled");
    }
  }
  return lines;
}

