// Unit tests for the pure splitting logic in lib/split.mjs.
import { test } from "node:test";
import assert from "node:assert/strict";
import { computeShares, settle, renderLines } from "./split.mjs";

test("computeShares: even split", () => {
  assert.deepEqual(computeShares(200, 2), [100, 100]);
  assert.deepEqual(computeShares(300, 3), [100, 100, 100]);
});

test("computeShares: remainder lands on first people by default (bug-compatible)", () => {
  // 100 / 3 -> share 33, remainder 1 -> first person gets the extra cent.
  assert.deepEqual(computeShares(100, 3), [34, 33, 33]);
  assert.deepEqual(computeShares(101, 3), [35, 33, 33]);
  assert.deepEqual(computeShares(102, 3), [34, 34, 34]);
});

test("computeShares: start offset rotates the extra cents", () => {
  assert.deepEqual(computeShares(100, 3, 0), [34, 33, 33]);
  assert.deepEqual(computeShares(100, 3, 1), [33, 34, 33]);
  assert.deepEqual(computeShares(100, 3, 2), [33, 33, 34]);
});

test("computeShares: shares always sum to cents", () => {
  for (let cents = 0; cents <= 205; cents += 7) {
    for (const n of [1, 2, 3, 5]) {
      const shares = computeShares(cents, n);
      assert.equal(shares.reduce((a, b) => a + b, 0), cents);
    }
  }
});

test("computeShares rejects bad input", () => {
